@Override // com.macrovideo.v380.fragments.BaseFragment
protected void onClicked(View view) {
    int i;
    int id = view.getId();
    if (id == R.id.btn_left_common_top_bar) {
        onBackPressed();
        return;
    }
    if (id == R.id.ll_light_open) {
        showImage(1);
        return;
    }
    if (id == R.id.ll_light_close) {
        showImage(2);
        return;
    }
    if (id == R.id.ll_light_auto) {
        showImage(0);
        return;
    }
    if (id == R.id.ll_timing) {
        if (this.action == 1) {
            this.action = 2;
            ((FragmentConfigSettingWhileLightBinding) this.binding).ivLightTiming.setImageResource(R.drawable.common_btn_switchoff_nor);
            ((FragmentConfigSettingWhileLightBinding) this.binding).llSelectTime.setVisibility(8);
            return;
        } else {
            this.action = 1;
            ((FragmentConfigSettingWhileLightBinding) this.binding).ivLightTiming.setImageResource(R.drawable.common_btn_switchon_nor);
            ((FragmentConfigSettingWhileLightBinding) this.binding).llSelectTime.setVisibility(0);
            return;
        }
    }
    if (id == R.id.ll_start_time) {
        showSelectStartTimeDialog();
        return;
    }
    if (id == R.id.ll_end_time) {
        showSelectEndTimeDialog();
        return;
    }
    if (id == R.id.cl_light_sensitivity) {
        DeviceConfigSettingActivity deviceConfigSettingActivity = this.mActivity;
        deviceConfigSettingActivity.showLightSensitivityDialog(deviceConfigSettingActivity.mDeviceInfo, this.mDeviceXParam);
        return;
    }
    if (id == R.id.cl_motion_light_detection_switch_with_main) {
        int i2 = this.motionDetectionSwitch;
        if (i2 != 0) {
            if (i2 == 1) {
                this.motionDetectionSwitch = 10;
                ((FragmentConfigSettingWhileLightBinding) this.binding).ivMotionLightDetectionSwitch.setVisibility(4);
                return;
            } else {
                this.motionDetectionSwitch = 1;
                ((FragmentConfigSettingWhileLightBinding) this.binding).ivMotionLightDetectionSwitch.setVisibility(0);
                return;
            }
        }
        return;
    }
    if (id != R.id.cl_human_light_detection_switch || (i = this.humanDetectionSwitch) == 0) {
        return;
    }
    if (i == 1) {
        this.humanDetectionSwitch = 10;
        ((FragmentConfigSettingWhileLightBinding) this.binding).ivHumanLightDetectionSwitch.setVisibility(4);
    } else {
        this.humanDetectionSwitch = 1;
        ((FragmentConfigSettingWhileLightBinding) this.binding).ivHumanLightDetectionSwitch.setVisibility(0);
    }
}
